<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Bouncing Ball Physics Playground</title>
    <style>
        body {
            background-color: #1e1e2e; /* Dark background */
            color: #cdd6f4;
            font-family: 'Arial', sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            margin: 0;
            padding: 20px;
        }

        #controls {
            margin-bottom: 20px;
            display: flex;
            gap: 15px;
        }

        button {
            background-color: #313244;
            border: 1px solid #45475a;
            color: #cdd6f4;
            padding: 8px 15px;
            cursor: pointer;
            transition: background-color 0.15s, border-color 0.15s;
            border-radius: 4px;
        }

        button:hover {
            background-color: #45475a;
            border-color: #585b70;
        }

        #simContainer {
            position: relative;
            /* Define a visible bounding area for the canvas */
            width: 600px; /* Max CSS width */
            height: 600px; /* Max CSS height */
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.4);
        }

        #sim {
            background-color: #181825; /* Inner canvas background */
            display: block;
            /* Ensure the actual canvas size is handled by JS to be >= 400x400 pixels */
            width: 100%;
            height: 100%;
        }

        h1 {
            color: #89b4fa;
        }
    </style>
</head>
<body>

    <h1>🌌 Bouncing Ball Playground</h1>
    <div id="controls">
        <button id="drop">Drop Ball</button>
        <button id="play">Start Simulation</button>
        <button id="clear">Clear All</button>
    </div>

    <div id="simContainer">
        <canvas id="sim"></canvas>
    </div>


    <script>
        // --- CONSTANTS AND INITIALIZATION ---
        const canvas = document.getElementById('sim');
        const ctx = canvas.getContext('2d');

        const CANVAS_W = 800; // Internal drawing resolution width (Must be >= 400)
        const CANVAS_H = 600; // Internal drawing resolution height (Must be >= 400)

        canvas.width = CANVAS_W;
        canvas.height = CANVAS_H;

        // Simulation parameters
        let balls = [];
        const GRAVITY = 9.8 / 100; // Scaled gravity for smoother simulation steps
        const RESTITUTION = 0.95;  // Energy loss on bounce
        const BALL_COLOR = '#fab38b';

        let isRunning = false;
        let animationFrameId = null;
        const TIME_STEP = 1 / 60; // Target simulation delta time (dt)

        // --- UTILITY FUNCTIONS ---

        /**
         * Draws the current state of all balls on the canvas.
         */
        function draw() {
            ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);

            balls.forEach(ball => {
                ctx.beginPath();
                ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
                ctx.fillStyle = BALL_COLOR;
                ctx.fill();
                ctx.closePath();
            });
        }

        /**
         * Updates the physics for one time step (dt). Handles movement, gravity, and collisions.
         * @param {number} dt - Time delta step.
         */
        function updatePhysics(dt) {
            for (let i = 0; i < balls.length; i++) {
                const ball = balls[i];

                // 1. Apply Gravity
                ball.vy += GRAVITY * dt;

                // 2. Update Position
                ball.x += ball.vx * dt;
                ball.y += ball.vy * dt;

                // 3. Collision Detection & Response (Edges)

                // Bounce off Left/Right Walls (X-axis boundaries)
                if (ball.x - ball.r < 0) {
                    ball.x = ball.r; // Clamp position
                    ball.vx *= -RESTITUTION; // Reverse and lose energy
                } else if (ball.x + ball.r > CANVAS_W) {
                    ball.x = CANVAS_W - ball.r; // Clamp position
                    ball.vx *= -RESTITUTION;
                }

                // Bounce off Top/Bottom Walls (Y-axis boundaries)
                if (ball.y - ball.r < 0) {
                    ball.y = ball.r; // Clamp position
                    ball.vy *= -RESTITUTION;
                } else if (ball.y + ball.r > CANVAS_H) {
                    ball.y = CANVAS_H - ball.r; // Clamp position
                    ball.vy *= -RESTITUTION;
                    // Optional: Add a small friction effect when hitting the floor/ceiling
                    // This helps stabilize things if GRAVITY was too high
                }

                // 4. Cleanup (Remove balls that fall too far away or have minimal energy)
                if (ball.r > 0 && Math.abs(ball.vx) < 1 && Math.abs(ball.vy) < 1 && ball.y > CANVAS_H + 50) {
                    // Mark for removal by swapping/filtering later, or simply skip it if we were using a pool system.
                }
            }

            // Simple cleanup: Filter out balls that have effectively stopped and fallen off screen (though the bounds check should handle most of this)
            balls = balls.filter(ball => {
                 return ball.r > 0 && ball.y < CANVAS_H + 50;
            });
        }

        /**
         * Main simulation loop function called by requestAnimationFrame.
         */
        function gameLoop() {
            if (!isRunning) return;

            // Update physics state
            updatePhysics(TIME_STEP);

            // Redraw the canvas
            draw();

            animationFrameId = requestAnimationFrame(gameLoop);
        }


        // --- API IMPLEMENTATION (window.sim object) ---

        window.sim = {
            w: CANVAS_W,
            h: CANVAS_H,

            /**
             * Returns a copy of the current list of balls.
             */
            balls: function() {
                return [...balls]; 
            },

            /**
             * Adds a new ball to the simulation state.
             * @param {number} x - Initial X position.
             * @param {number} y - Initial Y position.
             * @param {number} [vx=0] - Initial velocity X component.
             * @param {number} [vy=0] - Initial velocity Y component.
             * @param {number} [r=15] - Radius of the ball.
             */
            addBall: function(x, y, vx = 0, vy = 0, r = 15) {
                const newBall = { x, y, vx, vy, r };
                balls.push(newBall);
            },

            /**
             * Removes all balls from the simulation state.
             */
            clear: function() {
                balls = [];
            },

            /**
             * Advances the simulation one step and redraws.
             * @param {number} [dt=1] - Time step delta.
             */
            step: function(dt = 1) {
                 // Note: For manual testing/grading, we simulate the update but must ensure a redraw happens.
                updatePhysics(dt);
                draw();
            }
        };


        // --- EVENT LISTENERS AND INITIALIZATION ---

        /**
         * Handles click events on the canvas to spawn a ball at the cursor position.
         */
        canvas.addEventListener('click', (e) => {
            const rect = canvas.getBoundingClientRect();
            // Calculate coordinates relative to the internal high-resolution canvas size
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Spawn a ball with some initial horizontal velocity for fun
            sim.addBall(x, y, (Math.random() - 0.5) * 10, Math.random() * 5 + 5); 
        });


        document.getElementById('drop').addEventListener('click', () => {
            // Spawn a ball near the top center with slight downward velocity
             const x = CANVAS_W / 2 + (Math.random() - 0.5) * 100;
             const y = 30;
             sim.addBall(x, y, 0, 5); 
        });

        document.getElementById('clear').addEventListener('click', () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
                animationFrameId = null;
            }
            isRunning = false;
            sim.clear();
            draw();
        });

        document.getElementById('play').addEventListener('click', () => {
            if (!isRunning) {
                // Start the simulation loop
                isRunning = true;
                gameLoop();
                document.getElementById('play').textContent = 'Pause Simulation';
            } else {
                // Pause the simulation loop
                isRunning = false;
                cancelAnimationFrame(animationFrameId);
                animationFrameId = null;
                document.getElementById('play').textContent = 'Start Simulation';
            }
        });


        // Initial setup: Draw an empty state and start paused
        draw();

    </script>
</body>
</html>
